; Joystick port 2 read: LDA $DC00 then decodes Up/Down/Left/Right into $0339/$033A X/Y deltas and $033B fire. Called from game loop, menu and high-score entry.
read_joystick2      lda $dc00            ; CIA1 Port A = Joystick 2 ; x-ref: $271b, $2d29, $2e20, $2e31, $2f33, ...; CIA1: Data Port Register A
                    ldy #$00
                    ldx #$00
                    lsr a
                    bcs joy_check_up
                    dey 
joy_check_up        lsr a                ; Up bit clear (pressed) -> Y-1 ; x-ref: $17a8
                    bcs joy_check_down
                    iny 
joy_check_down      lsr a                ; Down bit clear -> Y+1 ; x-ref: $17ac
                    bcs joy_check_left   ; Up: Y-1
                    dex 
joy_check_left      lsr a                ; Left bit clear -> X-1 ; x-ref: $17b0
                    bcs joy_check_right
                    inx                  ; Left: X-1
joy_check_right     lsr a                ; Right bit clear -> X+1; next carry is fire bit ; x-ref: $17b4
                    stx joy_x_delta
                    sty joy_y_delta
                    ldx #$00             ; Fire bit -> $033B
                    bcs joy_check_fire
                    inx 
joy_check_fire      stx joy_fire         ; Fire pressed -> joy_fire=1 else 0 ; x-ref: $17c0
                    rts 
